// The preview uses an explicit feeling, never pretends to interpret private writing.
// An AI integration must produce a validated path ID; scripture remains sourced text.
export const PATHS = {
  sad:{theme:'rest',actions:['sadPrayer','gentleWalk','tellSomeone'],label:'sadPath',reflection:'sadReflection'},
  hopeless:{theme:'hope',actions:['goodNews','smallGood','visitElders'],label:'worldPath',reflection:'worldReflection'},
  anxious:{theme:'peace',actions:['grounding','worryPrayer','oneThing'],label:'anxietyPath',reflection:'anxietyReflection'},
  lonely:{theme:'belonging',actions:['reachOut','community','visitElders'],label:'lonelyPath',reflection:'lonelyReflection'},
  overwhelmed:{theme:'rest',actions:['oneThing','restPrayer','gentleWalk'],label:'overwhelmedPath',reflection:'overwhelmedReflection'},
  grateful:{theme:'gratitude',actions:['thankYou','smallGood','rememberGood'],label:'gratefulPath',reflection:'gratefulReflection'},
  peaceful:{theme:'peace',actions:['quietPrayer','rememberGood','reachOut'],label:'peacefulPath',reflection:'peacefulReflection'},
  hopeful:{theme:'hope',actions:['oneHope','smallGood','thankYou'],label:'hopefulPath',reflection:'hopefulReflection'},
  unsure:{theme:'hope',actions:['grounding','quietPrayer','tellSomeone'],label:'unsurePath',reflection:'unsureReflection'}
};
export function journeyPath(mood){return PATHS[mood]??PATHS.unsure;}
export function journeyPassages(passages,mood){
  const theme=journeyPath(mood).theme;
  const specific=passages.filter(p=>p.situations?.includes(mood));
  return [...specific,...passages.filter(p=>p.theme===theme&&!specific.includes(p))].slice(0,2);
}
